<?php declare(strict_types=1); namespace App\Controllers\Admin; use App\Core\{Auth,Csrf,Database as DB,Request,Response,Session,View,Migrator};
final class SalesSetupController { public function index(Request $r): string { Auth::require($r); $ready=false; try{$ready=(bool)DB::scalar("SELECT COUNT(*) FROM schema_migrations WHERE version LIKE '2026_11_14%'");}catch(\Throwable $e){} return View::page('admin.sales.setup',['title'=>'Sales module setup','ready'=>$ready],'layouts.admin'); } public function install(Request $r): never { Auth::require($r); Csrf::check($r); try{$out=(new Migrator())->migrate(); Session::flash('success','Sales module installed or already up to date. '.count($out).' migration file(s) checked.');}catch(\Throwable $e){Session::flash('error','Sales module setup failed: '.$e->getMessage());} Response::redirect('/admin/sales/setup'); } }
